@pytest.mark.parametrize('provider', ['openai', 'anthropic']) @pytest.mark.parametrize('case', ['soft_note', 'prose', 'capacity']) def test_recovery_native_http_roundtrip(provider, case, tmp_path): corpus = smoke_corpus() config = Config(max_model_calls=3) if case == 'soft_note': replies = [S, R, native(note(), ('finish', {'answer': 'Ada Rowan', 'refs': ['e1']}))] elif case == 'prose': replies = [S, R, native(content='RAW_REPAIR_778 "Ada Rowan"', finish_reason='stop'), F] config = Config(max_model_calls=4) else: corpus = LocalCorpus([{'docid': 'large', 'title': 'LongArchive', 'content': 'X' * 26000}]) config = Config(max_model_calls=3, context_limit=28000, response_reserve=2048) replies = [native(('search', {'queries': ['LongArchive'], 'top_k': 1})), native(*[('read', {'ref': 'd1', 'start': i * 6000, 'length': 6000}) for i in range(4)]), A] received = [] queue = deepcopy(replies) class Handler(BaseHTTPRequestHandler): def log_message(self, *args): pass def do_POST(self): body = json.loads(self.rfile.read(int(self.headers['Content-Length']))) received.append(body) raw = queue.pop(0) payload = anthropic(raw) if provider == 'anthropic' else raw self.send_response(200) self.send_header('Content-Type', 'application/json') self.end_headers() self.wfile.write(json.dumps(payload).encode()) server = ThreadingHTTPServer(('127.0.0.1', 0), Handler) thread = threading.Thread(target=server.serve_forever, daemon=True) thread.start() h = Harness('Who was first?', corpus, path=tmp_path/'episode.sqlite', config=config) cls = AnthropicModel if provider == 'anthropic' else OpenAIModel model = cls(f'http://127.0.0.1:{server.server_port}/v1', 'fixture', revision='offline', http=HTTP(allow_network=True)) try: terminal = h.run(model) > assert terminal['outcome'] == ('abstained' if case == 'capacity' else 'submitted') E AssertionError: assert 'transport_error' == 'submitted' E E - submitted E + transport_error
